 "content": "def transform(grid):
    """Complete a three-panel L of reflected motifs in a 2x2 panel block."""
    h, w = len(grid), len(grid[0])
    # Full, uniform non-background lines are the panel separators.
    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    if not sep_rows or not sep_cols:
        return [row[:] for row in grid]

    def intervals(length, cuts):
        spans = []
        start = 0
        for cut in cuts:
            if start < cut:
                spans.append((start, cut))
            start = cut + 1
        if start < length:
            spans.append((start, length))
        return spans

    row_spans = intervals(h, sep_rows)
    col_spans = intervals(w, sep_cols)
    out = [row[:] for row in grid]

    def panel_cells(pr, pc):
        r0, r1 = row_spans[pr]
        c0, c1 = col_spans[pc]
        return {(r-r0, c-c0): grid[r][c]
                for r in range(r0, r1) for c in range(c0, c1)
                if grid[r][c] != 0}

    def reflected(cells, height, width, flip_r=False, flip_c=False):
        return {((height-1-r if flip_r else r),
                 (width-1-c if flip_c else c)): color
                for (r, c), color in cells.items()}

    nrows, ncols = len(row_spans), len(col_spans)
    panels = [[panel_cells(r, c) for c in range(ncols)] for r in range(nrows)]
    for r in range(nrows - 1):
        for c in range(ncols - 1):
            positions = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
            occupied = [pos for pos in positions if panels[pos[0]][pos[1]]]
            if len(occupied) != 3:
                continue
            colors = {color for pr, pc in occupied
                      for color in panels[pr][pc].values()}
            if len(colors) != 1:
                continue
            missing = next(pos for pos in positions if pos not in occupied)
            mr, mc = missing
            mh = row_spans[mr][1] - row_spans[mr][0]
            mw = col_spans[mc][1] - col_spans[mc][0]
            if any(row_spans[pr][1] - row_spans[pr][0] != mh or
                   col_spans[pc][1] - col_spans[pc][0] != mw
                   for pr, pc in occupied):
                continue

            # The known cells must obey the same horizontal/vertical reflection rule.
            valid = True
            for a in occupied:
                for b in occupied:
                    if a >= b:
                        continue
                    if a[0] == b[0]:
                        expected = reflected(panels[a[0]][a[1]], mh, mw, flip_c=True)
                        if b[1] == a[1] + 1 and expected != panels[b[0]][b[1]]:
                            valid = False
                    elif a[1] == b[1]:
                        expected = reflected(panels[a[0]][a[1]], mh, mw, flip_r=True)
                        if b[0] == a[0] + 1 and expected != panels[b[0]][b[1]]:
                            valid = False
            if not valid:
                continue

            candidates = []
            for pr, pc in occupied:
                if pr == mr:
                    candidates.append(reflected(panels[pr][pc], mh, mw, flip_c=True))
                elif pc == mc:
                    candidates.append(reflected(panels[pr][pc], mh, mw, flip_r=True))
            if not candidates or any(candidate != candidates[0] for candidate in candidates[1:]):
                continue
            r0, _ = row_spans[mr]
            c0, _ = col_spans[mc]
            for (dr, dc), color in candidates[0].items():
                out[r0 + dr][c0 + dc] = color
    return out
